 html+=visual.roi(s,r)+table([['Choix','Avec cet achat','Sans cet achat'],['Gagné en plus après '+hours(s.roi.hours)+' de jeu',money(r.netProfit),money(0)]],'Avec ou sans cet achat · même temps de jeu, sans compter ce que tu gagnais déjà',true);
 if(s.roi.mode==='improve')html+='<p>Sans l’achat : '+money(r.beforeNet)+' ; avec : '+money(r.afterNet)+'. On compte seulement la différence.</p>';
