  r.steps.forEach((st,i)=>{const isGoal=st.kind==='goal',when=st.atHours===0?'dès maintenant':'après '+hours(st.atHours)+' de jeu'+(st.days?' (≈ jour '+st.days+')':'');steps.push({title:(isGoal?(p.kind==='purchase'?'Achète ':'Objectif : ')+st.name:'Achète d’abord '+st.name)+' — '+when,text:isGoal?(p.kind==='purchase'?'C’est ton but. Le prix vient de ta fiche ou de ce que tu imagines.':'La somme que tu voulais, en plus de ce que tu gardes de côté.'):(st.waitHours>0?'Il faut d’abord jouer '+hours(st.waitHours)+' de plus pour le payer.':'Tu peux le payer tout de suite.'),detail:'Après cette étape : il te reste '+money(st.capitalAfter)+', tu gagnes '+money(st.hourlyAfter)+' par heure.',goal:isGoal});});
