  const list='<ol class="b-plan-steps">'+steps.map((x,i)=>'<li class="b-plan-step'+(x.goal?' is-goal':'')+'"><span class="calc-tag">'+(i+1)+'</span><div><h4>'+esc(x.title)+'</h4><p>'+esc(x.text)+'</p>'+(d&&x.detail?'<p class="calc-note">'+esc(x.detail)+'</p>':'')+'</div></li>').join('')+'</ol>';
