 $('order-capital-summary').textContent='Tu as '+money(s.goal.capital)+' · tu gagnes '+money(s.goal.hourly)+' par heure de jeu. On compte ce que tu gagnes seulement pendant le temps où tu attends d’avoir assez.';
 document.querySelectorAll('[data-b-order-key]').forEach(el=>{const a=lookup(el.dataset.bOrderKey);if(!a)return;el.querySelector('.b-order-head strong').textContent=(s.order.keys.indexOf(a.key)+1)+'. '+a.name;el.querySelector('.b-order-head p').textContent=(labels[itemFor(a)?.type]||'Achat libre')+' · '+orderPrice(a);el.querySelector('[data-b-order-up]').setAttribute('aria-label','Monter '+a.name);el.querySelector('[data-b-order-down]').setAttribute('aria-label','Descendre '+a.name);});
 mode();sessionRender();roiRender();orderRender();budgetRender();renderPlan();
