 function afterEdit(){state().completed=[];api.changed();}
 function refresh(focus){api.mount();api.saveLocal();if(focus){const el=$(focus);if(el){el.focus({preventScroll:true});const r=el.getBoundingClientRect(),top=(document.querySelector('header')?.getBoundingClientRect().bottom||0)+20;if(r.top<top||r.bottom>innerHeight-24)el.scrollIntoView({block:'center',behavior:'instant'});}}}
 function search(el){combo=el;comboIndex=-1;const q=el.value;comboRows=choices.filter(x=>api.searchMatch(x,q)).slice(0,12);const list=$(el.id+'-list');list.innerHTML=comboRows.map((x,i)=>'<div class="b-suggestion" role="option" id="'+el.id+'-option-'+i+'" aria-selected="false" data-b-suggestion="'+i+'">'+media(x)+'<span><strong>'+esc((x.brand?x.brand+' ':'')+x.name)+'</strong><small>'+esc(labels[x.type]||x.category)+' · '+(x.price===null?'prix inconnu':money(x.price))+'</small></span></div>').join('');list.hidden=!comboRows.length;el.setAttribute('aria-expanded',String(!!comboRows.length));el.removeAttribute('aria-activedescendant');$(el.id+'-feedback').textContent=comboRows.length?comboRows.length+' suggestion(s), flèches puis Entrée pour choisir.':'Aucun achat correspondant dans le catalogue.';}
