  if(el.id==='budget-category'){budgetCategory=Number(el.value);$('budget-amount').innerHTML=field('budget.allocations.'+budgetCategory,'Montant de ce poste ($)',s.budget.allocations[budgetCategory]);return true;}
  if(el.dataset.field==='roi.mode'||el.dataset.field==='roi.recoveryActivity'||el.dataset.field==='plan.kind'||el.dataset.field==='plan.activity'||el.dataset.field==='plan.priority'||el.dataset.field==='compare.criterion'){api.setPath(el.dataset.field,el.value);refresh(el.id);return true;}
  if(el.dataset.field&&/^assets\.\d+\.utility$/.test(el.dataset.field)){api.setPath(el.dataset.field,Number(el.value));afterEdit();return true;}
  if(el.dataset.bPlanPrereq!==undefined){s.plan.usePrerequisites=el.checked;refresh();return true;}
