  if(d.bOrderCurrent||d.bOrderRoi||d.bOrderRoiIncome){const key=d.bOrderCurrent?s.purchase.key:s.roi.key;if(!s.order.keys.includes(key))s.order.keys.push(key);if(d.bOrderRoiIncome)lookup(key).incomeMode='roi';orderEditor=key;s.tab='order';refresh('order-search');return true;}
  if(d.bRoiManual||d.bRoiAlternative){if(s.assets.length>=40){api.notify('Quarante achats maximum.');return true;}const key='free-'+Date.now().toString(36)+'-'+s.assets.length;s.assets.push({key,itemId:'',name:d.bRoiAlternative?'Mon autre achat':'Mon achat libre',price:null,referencePrice:null,extras:0,fees:0,owned:false,incomeMode:'none',boostHourly:0});if(d.bRoiAlternative)s.roi.compareKey=key;else{s.roi.key=key;s.purchase.key=key;s.roi.activityIds=[];s.roi.mode='estimate';}refresh(d.bRoiAlternative?'roi-alternative-price':'f-roi-purchase');return true;}
