  if(d.bOrderUp||d.bOrderDown){const key=d.bOrderUp||d.bOrderDown,i=s.order.keys.indexOf(key),j=i+(d.bOrderUp?-1:1);if(j>=0&&j<s.order.keys.length)[s.order.keys[i],s.order.keys[j]]=[s.order.keys[j],s.order.keys[i]];refresh();document.querySelector('[data-b-order-edit="'+CSS.escape(key)+'"]')?.focus({preventScroll:true});return true;}
  if(d.bOrderRemove){lastRemoved={key:d.bOrderRemove,index:s.order.keys.indexOf(d.bOrderRemove)};s.order.keys=s.order.keys.filter(x=>x!==d.bOrderRemove);refresh('order-search');return true;}
